insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('485b228e-d425-5d59-944c-92c49b80540a', 'gift-card-terms', '1.0', 1, 0, 0, '2026-10-01', 'CURRENT', true, '{"en": "# Gift Card Terms\n\nGift cards: purchase, redemption, balances, expiry and loss.\n\n## Scope\n\nThese terms apply to AfroTransact gift cards, digital and physical, and to promotional credit issued as a gift card. They sit alongside the Conditions of Use.\n\n## Buying a gift card\n\nGift cards are sold by AfroTransact, Inc. in US dollars. The amount, the recipient and any message are shown before you pay. A purchase is final once the card is delivered.\n\n## Redeeming\n\nEnter the code at checkout. A gift card can pay for products and services sold on AfroTransact, including items sold by independent sellers. It cannot be redeemed for cash except where the law requires, and cannot be used to buy another gift card.\n\n## Balance, expiry and fees\n\nGift cards do not expire and carry no fees. Check the balance in your account at any time. If an order is returned, the refund goes back to the gift card balance first.\n\n## Lost or stolen cards\n\nTreat a gift card like cash. Contact {support} with the order number and we will help where the code has not been redeemed. We are not responsible for a card once it has been used.\n\n## Questions\n\nWrite to {legal} or call {phone}."}'::jsonb, 'First draft', '2026-10-01T00:00:00Z', 'seed', '2026-10-01T00:00:00Z', null);
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('2378cc76-2d35-585d-8165-063852726ee5', 'store-credit-terms', '1.0', 1, 0, 0, '2026-10-01', 'CURRENT', true, '{"en": "# Store Credit Terms\n\nStore credit: how it is issued, used and when it lapses.\n\n## What store credit is\n\nStore credit is a balance on your account issued as a refund, goodwill gesture or promotion. It is not a deposit account and earns no interest.\n\n## Using store credit\n\nCredit is applied at checkout before your payment method. It can be used on products and services, but not on gift cards or membership fees.\n\n## Expiry\n\nCredit issued as a refund does not expire. Promotional credit shows its expiry date when it is issued and in your account.\n\n## Returns and cancellations\n\nIf you return an item bought with store credit, the refund goes back as store credit. Promotional credit that has expired is not restored.\n\n## Fraud and misuse\n\nWe may remove credit obtained through fraud, chargeback abuse or a breach of the Conditions of Use."}'::jsonb, 'First draft', '2026-10-01T00:00:00Z', 'seed', '2026-10-01T00:00:00Z', null);
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('3a34b4d2-d43f-5222-9f60-984198b5f2a9', 'membership-terms', '1.0', 1, 0, 0, '2026-10-01', 'CURRENT', true, '{"en": "# Membership Terms\n\nThe AfroTransact membership programme: fees, benefits, renewal and cancellation.\n\n## The programme\n\nMembership gives eligible orders delivery and other benefits described on the membership page when you join. Benefits can change; we give notice before any change takes effect.\n\n## Fees and renewal\n\nFees are shown in US dollars before you join. Membership renews at the end of each period at the then-current fee until you cancel. We email you before an annual renewal.\n\n## Free trials and promotions\n\nA trial converts to a paid membership unless cancelled before it ends. Promotional pricing applies only to the period stated.\n\n## Cancelling\n\nCancel in your account at any time. Benefits continue to the end of the paid period. Fees already paid are refunded only where the law requires or where we have not delivered the benefits.\n\n## Fair use\n\nBenefits are for personal use. We may end a membership that is used for resale or abuse, with a refund of the unused fee."}'::jsonb, 'First draft', '2026-10-01T00:00:00Z', 'seed', '2026-10-01T00:00:00Z', null);
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('d3ff934e-5589-5aa5-a820-ab5a6156becf', 'referral-terms', '1.0', 1, 0, 0, '2026-10-01', 'CURRENT', true, '{"en": "# Referral Program Terms\n\nInvite friends: who qualifies, when rewards are earned and what is not allowed.\n\n## How it works\n\nShare your referral link. When a new customer signs up with it and completes a qualifying first order, you and they each receive the reward shown in your account.\n\n## Qualifying\n\nThe friend must be new to AfroTransact, be a different person from you, and complete the first order within 30 days. Cancelled and returned orders do not qualify.\n\n## Rewards\n\nRewards are issued as store credit. They may expire as stated when issued and have no cash value.\n\n## What is not allowed\n\nSelf-referral, fake accounts, posting links as spam or paid advertising, and offering incentives that break the rules of a platform you use are not allowed. We may withhold rewards and close accounts that do this.\n\n## Changes\n\nWe may change or end the programme at any time. Rewards already earned stay yours."}'::jsonb, 'First draft', '2026-10-01T00:00:00Z', 'seed', '2026-10-01T00:00:00Z', null);
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('1c471544-278c-51e0-a239-e873e37393bc', 'preorder-delivery-terms', '1.0', 1, 0, 0, '2026-10-01', 'CURRENT', true, '{"en": "# Pre-order & Delivery Terms\n\nPre-orders: charging, delivery windows, delays and cancellation.\n\n## Pre-orders\n\nA pre-order reserves an item that is not yet available. The expected delivery window is shown on the listing and in your order.\n\n## Payment\n\nThe payment timing is shown before you order: either charged when you place the pre-order or when the item ships. Deposits are shown separately.\n\n## Delivery windows and delays\n\nIf the delivery window will be missed, we tell you promptly and give you the choice to wait or cancel for a full refund.\n\n## Cancelling\n\nYou can cancel a pre-order before it ships for a full refund of what you paid. Once shipped, the Returns & Refunds policy applies.\n\n## Delivery\n\nDelivery terms, risk of loss and failed-delivery handling follow the Conditions of Use and the carrier information in your order."}'::jsonb, 'First draft', '2026-10-01T00:00:00Z', 'seed', '2026-10-01T00:00:00Z', null);
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('3eeac5f5-bf5f-5db5-8d74-1c3302be7170', 'community-guidelines', '1.0', 1, 0, 0, '2026-10-01', 'CURRENT', true, '{"en": "# Community Guidelines\n\nWhat we expect in reviews, questions, messages and community spaces.\n\n## Be genuine\n\nWrite about your own experience. Do not post reviews you were paid or pressured to write, or reviews of your own business.\n\n## Be respectful\n\nNo harassment, hate speech, threats or discrimination. Keep disagreements about the product or service.\n\n## Keep it safe and lawful\n\nDo not share personal data of others, post illegal content or promote prohibited items.\n\n## Reporting\n\nReport content from the listing or message. We review reports promptly and may remove content, restrict features or close accounts that break these guidelines.\n\n## Appeals\n\nIf we remove your content or restrict your account, you can appeal by writing to {support}."}'::jsonb, 'First draft', '2026-10-01T00:00:00Z', 'seed', '2026-10-01T00:00:00Z', null);
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('7e7bf89c-831d-5f09-aed0-003849c16ff7', 'ip-policy', '1.0', 1, 0, 0, '2026-10-01', 'CURRENT', true, '{"en": "# Intellectual Property Policy\n\nReporting infringement and responding to a report.\n\n## Our approach\n\nWe respect intellectual property rights and expect sellers, providers and members to do the same. We remove content and listings when we receive a valid notice.\n\n## Reporting infringement\n\nSend a notice to {legal} identifying the work, the listing or content, your contact details, a statement of good faith belief and a statement that the notice is accurate under penalty of perjury, with your signature.\n\n## Responding to a notice\n\nWe tell the affected seller or provider, who may send a counter-notice. We may restore the content if the rights holder does not file a court action within the period the law allows.\n\n## Repeat infringers\n\nWe close the accounts of sellers and members who repeatedly infringe."}'::jsonb, 'First draft', '2026-10-01T00:00:00Z', 'seed', '2026-10-01T00:00:00Z', null);
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('7f8bc410-899f-5f07-b68b-462e5a58f851', 'provider-terms', '1.0', 1, 0, 0, '2026-10-01', 'CURRENT', true, '{"en": "# Service Provider Terms\n\nTerms for providers who list and perform services on AfroTransact.\n\n## Agreement\n\nThese terms apply to individuals and businesses who offer services on AfroTransact. They add to the Conditions of Use, the Payments Terms and the Data Processing Addendum.\n\n## Independent providers\n\nYou are an independent provider, not an employee or agent of AfroTransact. You set your services, hold the licences and insurance your services require, and are responsible for the work.\n\n## Bookings and cancellations\n\nYou honour confirmed bookings and the cancellation policy shown to customers. Repeated no-shows can lead to restrictions.\n\n## Fees and payouts\n\nFees are shown in the fee schedule and in your Provider Hub. Payouts follow the Payments Terms.\n\n## Conduct and safety\n\nYou follow the Community Guidelines, the Prohibited and Restricted Items policy where relevant and applicable law. We may suspend providers for safety or fraud risks.\n\n## Ending\n\nYou may stop offering services at any time after completing confirmed bookings. We may suspend or end access for breach of these terms."}'::jsonb, 'First draft', '2026-10-01T00:00:00Z', 'seed', '2026-10-01T00:00:00Z', null);
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('4012f7c7-0bfc-5257-a925-c3160587f5ee', 'payments-terms', '1.0', 1, 0, 0, '2026-10-01', 'CURRENT', true, '{"en": "# Payments Terms\n\nHow payments, payouts, refunds and chargebacks work for sellers and providers.\n\n## Payment processing\n\nPayments are processed by Stripe. By selling or providing services you also accept Stripe’s Connected Account Agreement.\n\n## Payouts\n\nNet proceeds are paid out to your bank account on the schedule shown in your Seller Center or Provider Hub. We may hold payouts for risk review, disputes or missing information.\n\n## Refunds and chargebacks\n\nRefunds approved under the Returns & Refunds policy are deducted from your balance. You are responsible for chargebacks on your orders and may be asked for evidence.\n\n## Taxes\n\nWe collect and remit sales tax where marketplace facilitator laws require. You are responsible for your own income taxes and provide the tax information we request.\n\n## Reserves and set-off\n\nWe may keep a reserve or set off amounts you owe against future payouts, with notice."}'::jsonb, 'First draft', '2026-10-01T00:00:00Z', 'seed', '2026-10-01T00:00:00Z', null);
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('ba967523-7b15-5b53-8011-a165405f9691', 'subprocessors', '1.0', 1, 0, 0, '2026-10-01', 'CURRENT', true, '{"en": "# Subprocessors\n\nThe companies that process personal data for AfroTransact and what they do.\n\n## About this list\n\nAfroTransact uses subprocessors to run the marketplace. Each is bound by a data processing agreement. This page is updated before a new subprocessor starts processing.\n\n## Current subprocessors\n\nPayments: Stripe. Hosting and infrastructure: the cloud provider for the market you use. Email and messaging: our transactional email and SMS providers. Support tooling and analytics: providers named in the Cookie Notice.\n\n## Changes and objections\n\nCustomers who have signed the Data Processing Addendum are notified of changes. Write to {privacy} to object."}'::jsonb, 'First draft', '2026-10-01T00:00:00Z', 'seed', '2026-10-01T00:00:00Z', null);
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('61d72882-a699-5bec-a816-545300c222db', 'data-processing', '1.0', 1, 0, 0, '2026-10-01', 'CURRENT', true, '{"en": "# Data Processing Addendum\n\nHow AfroTransact and sellers or providers handle personal data of customers.\n\n## Scope and roles\n\nThis addendum applies where a seller or provider receives personal data of customers to fulfil orders or bookings. Each party is an independent controller of the data it holds for its own purposes.\n\n## Use limits\n\nYou use customer data only to fulfil the order or booking, provide support, meet legal duties and prevent fraud. You do not sell it or use it for marketing without consent.\n\n## Security\n\nYou protect the data with appropriate technical and organisational measures and report a personal data breach to {privacy} without undue delay.\n\n## Requests and deletion\n\nYou help with privacy requests promptly and delete customer data when you no longer need it.\n\n## Subprocessors and transfers\n\nYou may use subprocessors under written terms no less protective than this addendum. Transfers outside the customer’s country follow the safeguards the law requires."}'::jsonb, 'First draft', '2026-10-01T00:00:00Z', 'seed', '2026-10-01T00:00:00Z', null);
insert into legal_version (id, doc_type, version, major, minor, patch, effective_date, status, draft_banner, bodies, change_summary, created_at, created_by, updated_at, archived_at) values ('5fe64bf0-44b1-5e97-aafd-23699bcdb374', 'seller-fees', '1.0', 1, 0, 0, '2026-10-01', 'CURRENT', true, '{"en": "# Seller Fees & Charges\n\nPlans, referral fees, fulfilment and other charges for selling on AfroTransact.\n\n## Plans\n\nSellers choose a plan in Seller Center. The monthly or annual plan fee and the features included are shown when you choose.\n\n## Referral fees\n\nA referral fee is a percentage of the item price and shipping for each sale, by category, as shown in the fee schedule in Seller Center.\n\n## Fulfilment and shipping\n\nIf you use Fulfilled by AfroTransact, fulfilment and storage fees apply. Shipping labels bought through AfroTransact are charged at the rates shown at purchase.\n\n## Other charges\n\nAdvertising, returns processing and refunds administration fees are shown before you accept them.\n\n## Changes\n\nWe give at least 30 days’ notice of fee increases."}'::jsonb, 'First draft', '2026-10-01T00:00:00Z', 'seed', '2026-10-01T00:00:00Z', null);
